def minPath(grid, k):
    N = len(grid)
    min_value = float('inf')
    min_path = []

    for row in range(N):
        for col in range(N):
            # Check for each cell if it can be the starting point
            path = [(grid[row][col], row, col)]
            for step in range(k):
                # Get the next steps from the 4 possible neighbors
                neighbors = [
                    (row - 1, col), (row + 1, col),
                    (row, col - 1), (row, col + 1)
                ]
                next_steps = [grid[nr][nc] for nr, nc in neighbors if 0 <= nr < N and 0 <= nc < N]
                # Update the path with the smallest lexicographically next value
                if next_steps:
                    next_steps.sort()
                    path.append(next_steps[0])
                else:
                    break
            # Remove the path from the beginning if we have a full path
            if len(path) == k + 1:
                min_value = min(min_value, path[0][0])
                if min_value == path[0][0]:
                    min_path = path
                else:
                    min_path = []

    return [val for val, _, _ in min_path]
